 30→// Inject build shims using the inject plugin
 31→const injectShims = (): Plugin[] => {
 32→  const buildShims = path.resolve('./src/build-shims.js');
 33→  const commonInject = {
 34→    exclude: ['src/setupTests.ts'],
 35→    global: [buildShims, 'global'],
