 38→  return [
 39→    {
 40→      name: 'inject-build-process',
 41→      config: () => ({
 42→        // rename process.env in build mode so it doesn't get set to an empty object up by the vite:define plugin
 43→        // this isn't needed in serve mode, because vite:define doesn't empty it in serve mode. And defines also happen last anyways in serve mode.
 44→        define: {
 45→          'process.env': `_process.env`,
 46→        },
