112→export function FinancesApp() {
113→  const { isNarrowWidth } = useResponsive();
114→  useMetaThemeColor(isNarrowWidth ? theme.mobileViewTheme : undefined);
115→
116→  const dispatch = useDispatch();
117→  const { t } = useTranslation();
118→
119→  // TODO: Replace with `useAccounts` hook once it's updated to return the useQuery results.
120→  const { data: accounts, isFetching: isAccountsFetching } = useQuery(
121→    accountQueries.list(),
122→  );
123→
124→  const versionInfo = useSelector(state => state.app.versionInfo);
125→  const [notifyWhenUpdateIsAvailable] = useGlobalPref(
126→    'notifyWhenUpdateIsAvailable',
127→  );
128→  const [lastUsedVersion, setLastUsedVersion] = useLocalPref(
129→    'flags.updateNotificationShownForVersion',
130→  );
131→  const [staleThresholdHours] = useLocalPref('bankSyncStaleThresholdHours');
132→
133→  const multiuserEnabled = useMultiuserEnabled();
134→
135→  // Mutex for background bank sync triggered by visibility/focus changes.
136→  // useRef persists across re-renders and effect re-creations (the effect
137→  // depends on staleThresholdHours, so a closure-scoped let would reset to
138→  // false whenever the pref changes, allowing concurrent syncs).
139→  const isSyncingRef = useRef(false);
140→
141→  const init = useEffectEvent(() => {
142→    // Wait a little bit to make sure the sync button will get the
143→    // sync start event. This can be improved later.
144→    setTimeout(async () => {
145→      await dispatch(sync());
146→
147→      // After CRDT sync completes, trigger background bank sync for accounts
148→      // whose last sync is older than the configurable stale threshold.
149→      // CRDT sync must finish first to avoid SQLite race conditions.
150→      try {
151→        const allAccounts = await send('accounts-get');
152→        const linkedAccounts = (allAccounts || []).filter(
153→          a => a.account_sync_source && a.account_id,
154→        );
155→        const effectiveThreshold = (staleThresholdHours ?? 6) * 60 * 60 * 1000;
156→        const now = Date.now();
157→
158→        // Fetch consent status in one call to filter out expired-consent
159→        // accounts before syncing (avoids wasted Enable Banking API calls).
160→        const linkedIds = linkedAccounts.map(a => a.id);
161→        // CRITICAL: send() returns { statuses } directly. post() already
162→        // unwraps responseData.data, so there is NO extra .data layer.
163→        const syncStatuses =
164→          linkedIds.length > 0
165→            ? ((
166→                await send('enablebanking-sync-status', {
167→                  accountIds: linkedIds,
168→                })
169→              )?.statuses ?? {})
170→            : {};
171→
172→        const staleIds = linkedAccounts
173→          .filter(a => {
174→            const ebStatus = syncStatuses[a.id];
175→            // Skip EB accounts with expired consent
176→            if (
177→              ebStatus?.consent_valid_until &&
178→              new Date(ebStatus.consent_valid_until) <= new Date()
179→            ) {
180→              return false;
181→            }
182→            const lastSync = a.last_sync ? parseInt(a.last_sync, 10) : 0;
183→            return now - lastSync > effectiveThreshold;
184→          })
185→          .map(a => a.id);
186→
187→        if (staleIds.length > 0) {
188→          send('accounts-bank-sync', { ids: staleIds }).catch(() => {
189→            dispatch(
190→              addNotification({
191→                notification: {
192→                  id: 'sync-on-open-failed',
193→                  type: 'warning',
194→                  message: t('Background sync failed - check your connection'),
195→                },
196→              }),
197→            );
198→          });
199→        }
200→      } catch {
201→        // Non-blocking: don't surface errors from the sync-on-open check
202→      }
203→    }, 100);
204→
205→    async function run() {
206→      await global.Actual.waitForUpdateReadyForDownload(); // This will only resolve when an update is ready
207→      dispatch(
208→        addNotification({
209→          notification: {
210→            type: 'message',
211→            title: t('A new version of Actual is available!'),
212→            message: t(
213→              'Click the button below to reload and apply the update.',
214→            ),
215→            sticky: true,
216→            id: 'update-reload-notification',
217→            button: {
218→              title: t('Update now'),
219→              action: async () => {
220→                await global.Actual.applyAppUpdate();
221→              },
222→            },
223→          },
224→        }),
225→      );
226→    }
227→
228→    run();
229→  });
230→
231→  useEffect(() => init(), []);
232→
233→  // Bank sync check on visibility/focus changes. Lives in FinancesApp (not
234→  // App.tsx) because useLocalPref requires budget context - App.tsx renders
235→  // before any budget is loaded, so useLocalPref there produces the wrong
236→  // localStorage key ('undefined-bankSyncStaleThresholdHours').
237→  useEffect(() => {
238→    async function onVisibilityOrFocus() {
239→      // App.tsx already fires dispatch(sync()) (CRDT sync) on visibilitychange.
240→      // The two handlers run concurrently - this is acceptable because bank
241→      // sync reads from the EB API (not local DB) and is idempotent.
242→      if (document.hidden || isSyncingRef.current) return;
243→      isSyncingRef.current = true;
244→      try {
245→        const allAccounts = await send('accounts-get');
246→        const linkedAccounts = (allAccounts || []).filter(
247→          a => a.account_sync_source && a.account_id,
248→        );
249→        const effectiveThreshold = (staleThresholdHours ?? 6) * 60 * 60 * 1000;
250→        const now = Date.now();
251→
252→        const linkedIds = linkedAccounts.map(a => a.id);
253→        const syncStatuses =
254→          linkedIds.length > 0
255→            ? ((
256→                await send('enablebanking-sync-status', {
257→                  accountIds: linkedIds,
258→                })
259→              )?.statuses ?? {})
260→            : {};
261→
262→        const staleIds = linkedAccounts
263→          .filter(a => {
264→            const ebStatus = syncStatuses[a.id];
265→            if (
266→              ebStatus?.consent_valid_until &&
267→              new Date(ebStatus.consent_valid_until) <= new Date()
268→            ) {
269→              return false;
270→            }
271→            const lastSync = a.last_sync ? parseInt(a.last_sync, 10) : 0;
272→            return now - lastSync > effectiveThreshold;
273→          })
274→          .map(a => a.id);
275→
276→        if (staleIds.length > 0) {
277→          send('accounts-bank-sync', { ids: staleIds }).catch(() => {});
278→        }
279→      } catch {
280→        // Non-blocking: don't surface errors from background sync check
281→      } finally {
282→        isSyncingRef.current = false;
283→      }
284→    }
285→
286→    window.addEventListener('visibilitychange', onVisibilityOrFocus);
287→    window.addEventListener('focus', onVisibilityOrFocus);
288→    return () => {
289→      window.removeEventListener('visibilitychange', onVisibilityOrFocus);
290→      window.removeEventListener('focus', onVisibilityOrFocus);
291→    };
292→  }, [staleThresholdHours]);
293→
294→  useEffect(() => {
295→    dispatch(getLatestAppVersion());
296→  }, [dispatch]);
297→
298→  useEffect(() => {
299→    if (notifyWhenUpdateIsAvailable && versionInfo) {
300→      if (
301→        versionInfo.isOutdated &&
302→        lastUsedVersion !== versionInfo.latestVersion
