 73→  reload: () => {
 74→    if (window.navigator.serviceWorker == null) return;
 75→
 76→    // Unregister the service worker handling routing and then reload. This should force the reload
 77→    // to query the actual server rather than delegating to the worker
 78→    return window.navigator.serviceWorker
 79→      .getRegistration('/')
