107→  openFileDialog: async ({ filters = [] }) => {
108→    const FILE_ACCEPT_OVERRIDES = {
109→      // Safari on iOS requires explicit MIME/UTType values for some extensions to allow selection.
110→      qfx: [
111→        'application/vnd.intu.qfx',
112→        'application/x-qfx',
113→        'application/qfx',
114→        'application/ofx',
115→        'application/x-ofx',
116→        'application/octet-stream',
117→        'com.intuit.qfx',
118→      ],
119→    };
120→
121→    return new Promise(resolve => {
122→      let createdElement = false;
123→      // Attempt to reuse an already-created file input.
124→      let input = document.body.querySelector(
125→        'input[id="open-file-dialog-input"]',
126→      );
127→      if (!input) {
128→        createdElement = true;
129→        input = document.createElement('input');
130→      }
131→
132→      input.type = 'file';
133→      input.id = 'open-file-dialog-input';
134→      input.value = null;
135→
136→      const filter = filters.find(filter => filter.extensions);
137→      if (filter) {
138→        input.accept = filter.extensions
139→          .flatMap(ext => {
140→            const normalizedExt = ext.startsWith('.')
141→              ? ext.toLowerCase()
142→              : `.${ext.toLowerCase()}`;
143→            const overrides = FILE_ACCEPT_OVERRIDES[ext.toLowerCase()] ?? [];
144→            return [normalizedExt, ...overrides];
145→          })
146→          .join(',');
147→      }
148→
149→      input.style.position = 'absolute';
150→      input.style.top = '0px';
151→      input.style.left = '0px';
152→      input.style.display = 'none';
153→
154→      input.onchange = e => {
155→        const file = e.target.files[0];
156→        const filename = file.name.replace(/.*(\.[^.]*)/, 'file$1');
157→
158→        if (file) {
159→          const reader = new FileReader();
160→          reader.readAsArrayBuffer(file);
161→          reader.onload = async function (ev) {
162→            const filepath = `/uploads/${filename}`;
163→
164→            window.__actionsForMenu
165→              .uploadFile(filename, ev.target.result)
166→              .then(() => resolve([filepath]));
167→          };
168→          reader.onerror = function () {
169→            alert('Error reading file');
170→          };
171→        }
172→      };
173→
174→      // In Safari the file input has to be in the DOM for change events to
175→      // reliably fire.
176→      if (createdElement) {
177→        document.body.appendChild(input);
178→      }
179→
180→      input.click();
181→    });
182→  },
