 25→import { getCountryFromBrowser } from '@desktop-client/components/util/localeToCountry';
 26→import { authorizeEnableBank } from '@desktop-client/enablebanking';
 27→import { useEnableBankingStatus } from '@desktop-client/hooks/useEnableBankingStatus';
 28→import { useGlobalPref } from '@desktop-client/hooks/useGlobalPref';
 29→import { pushModal } from '@desktop-client/modals/modalsSlice';
 30→import { useDispatch } from '@desktop-client/redux';
 31→
 32→type EnableBankingExternalMsgModalProps = {
 33→  sessionId?: string;
 34→  aspspName?: string;
 35→  aspspCountry?: string;
 36→  reauth?: boolean;
 37→};
 38→
 39→type AspspOption = {
 40→  id: string;
 41→  name: string;
 42→};
 43→
 44→function useAvailableBanks(country: string) {
 45→  const [banks, setBanks] = useState<AspspOption[]>([]);
 46→  const [isLoading, setIsLoading] = useState(false);
 47→  const [isError, setIsError] = useState(false);
 48→
 49→  useEffect(() => {
 50→    async function fetch() {
 51→      setIsError(false);
 52→
 53→      if (!country) {
 54→        setBanks([]);
 55→        setIsLoading(false);
 56→        return;
 57→      }
 58→
 59→      setIsLoading(true);
 60→
 61→      const { data, error } = await sendCatch('enablebanking-get-banks', {
 62→        country,
 63→      });
 64→
 65→      if (error || !Array.isArray(data)) {
 66→        setIsError(true);
 67→        setBanks([]);
 68→      } else {
 69→        // Enable Banking ASPSPs have a `name` field; map to autocomplete format
 70→        const options: AspspOption[] = data.map(
 71→          (aspsp: { name: string; country?: string }) => ({
 72→            id: aspsp.name,
 73→            name: aspsp.name,
 74→          }),
 75→        );
 76→        setBanks(options);
 77→      }
 78→
 79→      setIsLoading(false);
 80→    }
 81→
 82→    fetch();
 83→  }, [country]);
 84→
 85→  return {
 86→    data: banks,
 87→    isLoading,
 88→    isError,
 89→  };
 90→}
 91→
 92→function renderError(
 93→  error: { code: 'unknown' | 'timeout'; message?: string },
 94→  t: ReturnType<typeof useTranslation>['t'],
 95→) {
 96→  return (
 97→    <Error style={{ alignSelf: 'center', marginBottom: 10 }}>
 98→      {error.code === 'timeout'
 99→        ? t('Timed out. Please try again.')
100→        : t(
101→            'An error occurred while linking your account, sorry! The potential issue could be: {{ message }}',
102→            { message: error.message },
103→          )}
104→    </Error>
105→  );
106→}
107→
108→// Error fallback shown when the OAuth flow or bank-fetch renders throw.
109→// Catches errors from useAvailableBanks, sendCatch calls, and authorizeEnableBank.
110→function EBModalErrorFallback({
111→  error: rawError,
112→  resetErrorBoundary,
113→}: FallbackProps) {
114→  const { t } = useTranslation();
115→  const errorMessage =
116→    rawError instanceof globalThis.Error ? rawError.message : String(rawError);
117→
118→  return (
119→    <View style={{ padding: 20, alignItems: 'center' }}>
120→      <Paragraph style={{ color: theme.errorText, marginBottom: 10 }}>
121→        {t('Something went wrong with the bank connection flow.')}
122→      </Paragraph>
123→      <Paragraph
124→        style={{ fontSize: 12, color: theme.pageTextLight, marginBottom: 15 }}
125→      >
126→        {errorMessage}
127→      </Paragraph>
128→      <Button variant="primary" onPress={resetErrorBoundary}>
129→        {t('Try again')}
130→      </Button>
131→    </View>
132→  );
133→}
