135→export function EnableBankingExternalMsgModal({
136→  sessionId,
137→  aspspName,
138→  aspspCountry,
139→  reauth = false,
140→}: EnableBankingExternalMsgModalProps = {}) {
141→  const { t } = useTranslation();
142→  const dispatch = useDispatch();
143→  const [language] = useGlobalPref('language');
144→
145→  const browserTimezone =
146→    Intl.DateTimeFormat().resolvedOptions().timeZone || '';
147→  const browserLocale = language || navigator.language || 'en-US';
148→  const detectedCountry = getCountryFromBrowser(
149→    browserTimezone,
150→    browserLocale,
151→    COUNTRY_OPTIONS,
152→  );
153→
154→  const [waiting, setWaiting] = useState<string | null>(null);
155→  const [success, setSuccess] = useState<boolean>(false);
156→  // In re-auth mode, pre-fill bank and country from props to bypass the picker.
157→  // This ensures onJump() doesn't silently abort due to the guard
158→  // `if (!selectedBankId || !country) return`.
159→  const [selectedBankId, setSelectedBankId] = useState<string | undefined>(
160→    reauth ? aspspName : undefined,
161→  );
162→  const [country, setCountry] = useState<string | undefined>(
163→    reauth ? aspspCountry : detectedCountry,
164→  );
165→  const [error, setError] = useState<{
166→    code: 'unknown' | 'timeout';
167→    message?: string;
168→  } | null>(null);
169→
170→  const {
171→    data: bankOptions,
172→    isLoading: isBankOptionsLoading,
173→    isError: isBankOptionError,
174→  } = useAvailableBanks(country ?? '');
175→
176→  const { configured: isConfigured, isLoading: isConfigurationLoading } =
177→    useEnableBankingStatus();
178→
179→  async function onJump() {
180→    if (!selectedBankId || !country) return;
181→
182→    setError(null);
183→    setWaiting('browser');
184→
185→    try {
186→      const { accounts } = await authorizeEnableBank(selectedBankId, country);
187→
188→      if (reauth) {
189→        // Re-auth mode: swap the old session for the new one in eb_account_map.
190→        // The new session_id is shared by all accounts from the same OAuth flow.
191→        if (!accounts || accounts.length === 0) {
192→          setError({
193→            code: 'unknown',
194→            message: t('No accounts returned from re-authorization'),
195→          });
196→          setWaiting(null);
197→          return;
198→        }
199→
200→        const newSessionId = accounts[0].session_id;
201→
202→        await send('enablebanking-reauth-complete', {
203→          newSessionId,
204→          oldSessionId: sessionId,
205→        });
206→
207→        // Trigger an immediate sync so the user sees fresh data after re-auth.
208→        send('accounts-bank-sync', { ids: [] }).catch(() => {});
209→
210→        setWaiting(null);
211→        setSuccess(true);
212→      } else {
213→        dispatch(
214→          pushModal({
215→            modal: {
216→              name: 'select-linked-accounts',
217→              options: {
218→                externalAccounts: accounts,
219→                syncSource: 'enableBanking',
220→              },
221→            },
222→          }),
223→        );
224→
225→        setWaiting(null);
226→        setSuccess(true);
227→      }
228→    } catch (err: unknown) {
229→      const message =
230→        err instanceof globalThis.Error ? err.message : String(err);
231→      setError({
232→        code: message === 'timeout' ? 'timeout' : 'unknown',
233→        message: message !== 'timeout' ? message : undefined,
234→      });
235→      setWaiting(null);
236→    }
237→  }
238→
239→  const renderLinkButton = () => {
240→    return (
241→      <View style={{ gap: 10 }}>
242→        <FormField>
243→          <FormLabel
244→            title={t('Choose your country:')}
245→            htmlFor="country-field"
246→          />
247→          <Autocomplete
248→            strict
249→            highlightFirst
250→            suggestions={COUNTRY_OPTIONS}
251→            onSelect={setCountry}
252→            value={country}
253→            inputProps={{
254→              id: 'country-field',
255→              placeholder: t('(please select)'),
256→            }}
257→          />
258→        </FormField>
259→
260→        {isBankOptionError ? (
261→          <Error>
262→            <Trans>
263→              Failed loading available banks. Enable Banking may not be
264→              configured correctly. Please check your server settings.
265→            </Trans>
266→          </Error>
267→        ) : (
268→          country &&
269→          (isBankOptionsLoading ? (
270→            t('Loading banks...')
271→          ) : (
272→            <FormField>
273→              <FormLabel title={t('Choose your bank:')} htmlFor="bank-field" />
274→              <Autocomplete
275→                focused
276→                strict
277→                highlightFirst
278→                suggestions={bankOptions}
279→                onSelect={setSelectedBankId}
280→                value={selectedBankId}
281→                inputProps={{
282→                  id: 'bank-field',
283→                  placeholder: t('(please select)'),
284→                }}
285→              />
286→            </FormField>
287→          ))
288→        )}
289→
290→        <Warning>
291→          <Trans>
292→            By enabling bank sync, you will be granting Enable Banking (a third
293→            party service) read-only access to your account&apos;s transaction
294→            history. This service is not affiliated with Actual in any way. Make
295→            sure you&apos;ve read and understand Enable Banking&apos;s{' '}
296→            <Link
297→              variant="external"
298→              to="https://enablebanking.com/privacy-policy/"
299→              linkColor="purple"
300→            >
301→              Privacy Policy
302→            </Link>{' '}
303→            before proceeding.
304→          </Trans>
305→        </Warning>
306→
307→        <View style={{ flexDirection: 'row', gap: 10, alignItems: 'center' }}>
308→          <Button
309→            variant="primary"
310→            autoFocus
311→            style={{
312→              padding: '10px 0',
313→              fontSize: 15,
314→              fontWeight: 600,
315→              flexGrow: 1,
316→            }}
317→            onPress={onJump}
318→            isDisabled={!selectedBankId || !country}
319→          >
320→            <Trans>Link bank in browser</Trans> &rarr;
321→          </Button>
322→        </View>
323→      </View>
324→    );
325→  };
326→
327→  return (
328→    <Modal
329→      name="enablebanking-external-msg"
330→      containerProps={{ style: { width: 'clamp(400px, 30vw, 600px)' } }}
331→    >
332→      {({ state: { close } }) => (
333→        <>
334→          <ModalHeader
335→            title={
336→              reauth
337→                ? t('Re-authorize Bank (Enable Banking)')
338→                : t('Link Your Bank (Enable Banking)')
339→            }
340→            rightContent={<ModalCloseButton onPress={close} />}
341→          />
342→          <ErrorBoundary FallbackComponent={EBModalErrorFallback}>
343→            <View>
344→              <Paragraph style={{ fontSize: 15 }}>
345→                {reauth ? (
346→                  <Trans>
347→                    To re-authorize your bank connection, you will be redirected
348→                    to a new page where your bank will ask you to authorize
349→                    access again. Your existing accounts and transaction history
350→                    will not be affected.
351→                  </Trans>
352→                ) : (
353→                  <Trans>
354→                    To link your bank account, you will be redirected to a new
355→                    page where your bank will ask you to authorize access.
356→                    Enable Banking will not be able to withdraw funds from your
357→                    accounts.
358→                  </Trans>
359→                )}
360→              </Paragraph>
361→
362→              {error && (
363→                <>
364→                  {renderError(error, t)}
365→                  {reauth && (
366→                    <View style={{ alignItems: 'center', marginTop: 10 }}>
367→                      <Button variant="primary" onPress={onJump}>
368→                        <Trans>Try again</Trans>
369→                      </Button>
370→                    </View>
371→                  )}
372→                </>
373→              )}
374→
375→              {!error &&
376→                (waiting || isConfigurationLoading ? (
377→                  <View style={{ alignItems: 'center', marginTop: 15 }}>
378→                    <AnimatedLoading
379→                      color={theme.pageTextDark}
380→                      style={{ width: 20, height: 20 }}
381→                    />
382→                    <View style={{ marginTop: 10, color: theme.pageText }}>
383→                      {isConfigurationLoading
384→                        ? t('Checking Enable Banking configuration...')
385→                        : waiting === 'browser'
386→                          ? t('Waiting for bank authorization...')
387→                          : null}
388→                    </View>
389→
390→                    {waiting === 'browser' && (
391→                      <Link
392→                        variant="text"
393→                        onClick={onJump}
394→                        style={{ marginTop: 10 }}
395→                      >
396→                        (
397→                        <Trans>
398→                          Bank authorization not opening in a new tab? Click
399→                          here
400→                        </Trans>
401→                        )
402→                      </Link>
403→                    )}
404→                  </View>
405→                ) : success ? (
406→                  <Paragraph
407→                    style={{ marginTop: 10, color: theme.noticeTextLight }}
408→                  >
409→                    {reauth ? (
410→                      <Trans>
411→                        Success! Your bank connection has been re-authorized.
412→                        Syncing fresh transactions now. Please close this
413→                        window.
414→                      </Trans>
415→                    ) : (
416→                      <Trans>
417→                        Success! Your bank accounts are being linked. Please
418→                        close this window.
419→                      </Trans>
420→                    )}
421→                  </Paragraph>
422→                ) : isConfigured ? (
423→                  renderLinkButton()
424→                ) : (
425→                  <>
426→                    <Paragraph style={{ color: theme.errorText }}>
427→                      <Trans>
428→                        Enable Banking integration has not yet been configured.
429→                        Please contact your server administrator to set up the
430→                        Enable Banking API credentials.
431→                      </Trans>
432→                    </Paragraph>
433→                  </>
434→                ))}
435→            </View>
436→          </ErrorBoundary>
437→        </>
438→      )}
439→    </Modal>
440→  );
441→}
