const fs = require('fs');
const path = require('path');
const d = 'C:/Users/Eagi/projects/actual-budget-fork/packages/desktop-client/build';

const sw = fs.existsSync(path.join(d, 'sw.js'));
const swSize = sw ? fs.statSync(path.join(d, 'sw.js')).size : 0;
const mfExists = fs.existsSync(path.join(d, 'manifest.webmanifest'));
const siteExists = fs.existsSync(path.join(d, 'site.webmanifest'));
const mf = mfExists || siteExists;

const idx = fs.readFileSync(path.join(d, 'index.html'), 'utf8');
const hasCO = idx.includes('crossorigin');
const hasTH = idx.includes('theme-color');
const hasATI = idx.includes('apple-touch-icon');

// Check sw.js
const swContent = fs.readFileSync(path.join(d, 'sw.js'), 'utf8');
// Workbox generateSW minifies - look for precache array entries
const hasPrecacheEntries = swContent.includes('sql-wasm.wasm') && swContent.includes('site.webmanifest');
const hasEnablebanking = swContent.includes('enablebanking');
const wasmInSW = swContent.includes('.wasm');
const sqlInSW = swContent.includes('.sql');

// Count precache entries (approximate by counting url: occurrences)
const precacheCount = (swContent.match(/"url":/g) || []).length;

// Check manifest content
const mfPath = mfExists ? path.join(d, 'manifest.webmanifest') : path.join(d, 'site.webmanifest');
const mfContent = JSON.parse(fs.readFileSync(mfPath, 'utf8'));

const results = {
  sw_exists: sw,
  sw_size_kb: Math.round(swSize / 1024),
  manifest_file: mfExists ? 'manifest.webmanifest' : (siteExists ? 'site.webmanifest' : 'MISSING'),
  crossorigin_in_html: hasCO,
  theme_color_in_html: hasTH,
  apple_touch_icon_in_html: hasATI,
  sw_precache_entries_approx: precacheCount,
  sw_has_enablebanking_denylist: hasEnablebanking,
  sw_has_wasm: wasmInSW,
  sw_has_sql: sqlInSW,
  manifest_name: mfContent.name,
  manifest_display: mfContent.display,
  manifest_start_url: mfContent.start_url,
  manifest_theme_color: mfContent.theme_color,
  manifest_icons_count: mfContent.icons ? mfContent.icons.length : 0,
  manifest_has_maskable: mfContent.icons ? mfContent.icons.some(i => i.purpose === 'maskable') : false,
  manifest_has_512: mfContent.icons ? mfContent.icons.some(i => i.sizes === '512x512') : false,
};

console.log(JSON.stringify(results, null, 2));

const failures = [];
if (!sw) failures.push('sw.js missing');
if (swSize < 1024) failures.push('sw.js too small (<1KB)');
if (!mf) failures.push('manifest missing');
if (!hasCO) failures.push('crossorigin missing from index.html');
if (!hasTH) failures.push('theme-color missing from index.html');
if (!hasEnablebanking) failures.push('enablebanking denylist missing from sw.js');
if (!wasmInSW) failures.push('wasm not in sw.js precache');
if (!sqlInSW) failures.push('sql not in sw.js precache');
if (mfContent.name !== 'Actual') failures.push('manifest name wrong: ' + mfContent.name);
if (mfContent.icons && mfContent.icons.length < 4) failures.push('manifest icons count wrong');
if (precacheCount < 10) failures.push('precache entries count too low: ' + precacheCount);

if (failures.length > 0) {
  console.error('FAILURES:', failures.join(', '));
  process.exit(1);
} else {
  console.log('ALL CHECKS PASSED');
}

