  1→import React, { memo } from 'react';
  2→import { Trans } from 'react-i18next';
  3→
  4→import { Button } from '@actual-app/components/button';
  5→import { styles } from '@actual-app/components/styles';
  6→import { theme } from '@actual-app/components/theme';
  7→import { Tooltip } from '@actual-app/components/tooltip';
  8→import { format as formatDate } from 'date-fns';
  9→import type { Locale } from 'date-fns';
 10→
 11→import { tsToRelativeTime } from 'loot-core/shared/util';
 12→import type { AccountEntity } from 'loot-core/types/models';
 13→
 14→import { Cell, Row } from '@desktop-client/components/table';
 15→import { useEnableBankingSyncStatus } from '@desktop-client/hooks/useEnableBankingStatus';
 16→import { pushModal } from '@desktop-client/modals/modalsSlice';
 17→import { useDispatch } from '@desktop-client/redux';
 18→import {
 19→  getUrgencyLevel,
 20→  urgencyColors,
 21→} from '@desktop-client/utils/consent-urgency';
 22→
 23→type AccountRowProps = {
 24→  account: AccountEntity;
 25→  hovered: boolean;
 26→  onHover: (id: AccountEntity['id'] | null) => void;
 27→  onAction: (account: AccountEntity, action: 'link' | 'edit') => void;
 28→  locale: Locale;
 29→};
 30→
 31→export const AccountRow = memo(
 32→  ({ account, hovered, onHover, onAction, locale }: AccountRowProps) => {
 33→    const dispatch = useDispatch();
 34→    const backgroundFocus = hovered;
 35→
 36→    const lastSyncString = tsToRelativeTime(account.last_sync, locale, {
 37→      capitalize: true,
 38→    });
 39→    const lastSyncDateTime = formatDate(
 40→      new Date(parseInt(account.last_sync ?? '0', 10)),
 41→      'MMM d, yyyy, HH:mm:ss',
 42→      { locale },
 43→    );
 44→
 45→    // SYNC-07: Fetch Enable Banking-specific error details for EB accounts.
 46→    // Called unconditionally (React rules of hooks). Passes empty array for
 47→    // non-EB accounts so the hook is a no-op with no network cost.
 48→    const { statuses: ebStatuses } = useEnableBankingSyncStatus(
 49→      account.account_sync_source === 'enableBanking' ? [account.id] : [],
 50→    );
 51→    const ebStatus = ebStatuses?.[account.id];
 52→    const consentUrgencyColor = (() => {
 53→      const validUntil = ebStatus?.consent_valid_until;
 54→      if (!validUntil) return null;
 55→      const now = new Date();
 56→      const expiry = new Date(validUntil);
 57→      const daysUntilExpiry =
 58→        (expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24);
 59→      const urgency = getUrgencyLevel(daysUntilExpiry);
 60→      return urgency !== 'ok' ? { text: urgencyColors[urgency].text } : null;
 61→    })();
 62→    const consentValidUntil = ebStatus?.consent_valid_until
 63→      ? new Date(ebStatus.consent_valid_until).toLocaleDateString(undefined, {
 64→          month: 'short',
 65→          day: 'numeric',
 66→          year: 'numeric',
 67→        })
 68→      : null;
 69→    const consentIsExpired =
 70→      ebStatus?.consent_valid_until &&
 71→      new Date(ebStatus.consent_valid_until) <= new Date();
 72→
 73→    function handleReauth() {
 74→      dispatch(
 75→        pushModal({
 76→          modal: {
 77→            name: 'enablebanking-external-msg',
 78→            options: {
 79→              sessionId: ebStatus?.session_id ?? undefined,
 80→              aspspName: ebStatus?.aspsp_name ?? undefined,
 81→              aspspCountry: ebStatus?.aspsp_country ?? undefined,
 82→              reauth: true,
 83→            },
 84→          },
 85→        }),
 86→      );
 87→    }
 88→
 89→    const potentiallyTruncatedAccountName =
 90→      account.name.length > 30
 91→        ? account.name.slice(0, 30) + '...'
 92→        : account.name;
 93→
 94→    return (
 95→      <Row
 96→        height="auto"
 97→        style={{
 98→          fontSize: 13,
 99→          backgroundColor: backgroundFocus
100→            ? theme.tableRowBackgroundHover
101→            : theme.tableBackground,
102→        }}
103→        collapsed
104→        onMouseEnter={() => onHover && onHover(account.id)}
105→        onMouseLeave={() => onHover && onHover(null)}
106→        onFocus={() => onHover && onHover(account.id)}
107→        onBlur={() => onHover && onHover(null)}
108→      >
109→        <Cell
110→          name="accountName"
111→          width={250}
112→          plain
113→          style={{ color: theme.tableText, padding: '10px' }}
114→        >
115→          {potentiallyTruncatedAccountName}
116→        </Cell>
117→
118→        <Cell
119→          name="bankName"
120→          width="flex"
121→          plain
122→          style={{ color: theme.tableText, padding: '10px' }}
123→        >
124→          {account.bankName}
125→        </Cell>
126→
127→        {account.account_sync_source ? (
128→          <Tooltip
129→            placement="bottom start"
130→            content={
131→              lastSyncDateTime +
132→              (ebStatus?.status === 'error' && ebStatus?.error_message
133→                ? '\nError: ' + ebStatus.error_message
134→                : '')
135→            }
136→            style={{
137→              ...styles.tooltip,
138→            }}
139→          >
140→            <Cell
141→              name="lastSync"
142→              width={200}
143→              plain
144→              style={{
145→                color: theme.tableText,
146→                padding: '11px',
147→                textDecoration: 'underline',
148→                textDecorationStyle: 'dashed',
149→                textDecorationColor: theme.pageTextSubdued,
150→                textUnderlineOffset: '4px',
151→              }}
152→              data-vrt-mask
153→            >
154→              <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
155→                <span>{lastSyncString}</span>
156→                {ebStatus?.status === 'error' && ebStatus?.error_message ? (
157→                  <span
158→                    style={{
159→                      color: theme.errorText,
160→                      fontSize: 11,
161→                      fontWeight: 'normal',
162→                    }}
163→                  >
164→                    {ebStatus.error_message}
165→                  </span>
166→                ) : null}
167→                {consentValidUntil && consentUrgencyColor ? (
168→                  <span
169→                    style={{
170→                      color: consentUrgencyColor.text,
171→                      fontSize: 11,
172→                      fontWeight: 'normal',
173→                    }}
174→                  >
175→                    {consentIsExpired ? (
176→                      <Trans>Consent expired</Trans>
177→                    ) : (
178→                      <Trans>Consent expires {{ consentValidUntil }}</Trans>
