224→
225→        setWaiting(null);
226→        setSuccess(true);
227→      }
228→    } catch (err: unknown) {
229→      const message =
230→        err instanceof globalThis.Error ? err.message : String(err);
231→      setError({
232→        code: message === 'timeout' ? 'timeout' : 'unknown',
233→        message: message !== 'timeout' ? message : undefined,
