 11→// This file installs global variables that the app expects.
 12→// Normally these are already provided by electron, but in a real
 13→// browser environment this is where we initialize the backend and
 14→// everything else.
 15→
 16→const IS_DEV = process.env.NODE_ENV === 'development';
 17→const ACTUAL_VERSION = Platform.isPlaywright
 18→  ? '99.9.9'
 19→  : process.env.REACT_APP_REVIEW_ID
 20→    ? '.preview'
 21→    : packageJson.version;
 22→
 23→// *** Start the backend ***
 24→let worker = null;
 25→
 26→function createBackendWorker() {
 27→  worker = new Worker(backendWorkerUrl);
 28→  initSQLBackend(worker);
 29→
 30→  if (window.SharedArrayBuffer) {
 31→    localStorage.removeItem('SharedArrayBufferOverride');
 32→  }
 33→
 34→  worker.postMessage({
 35→    type: 'init',
 36→    version: ACTUAL_VERSION,
 37→    isDev: IS_DEV,
 38→    publicUrl: process.env.PUBLIC_URL,
 39→    hash: process.env.REACT_APP_BACKEND_WORKER_HASH,
 40→    isSharedArrayBufferOverrideEnabled: localStorage.getItem(
 41→      'SharedArrayBufferOverride',
 42→    ),
 43→  });
 44→}
