 48→let isUpdateReadyForDownload = false;
 49→let markUpdateReadyForDownload;
 50→const isUpdateReadyForDownloadPromise = new Promise(resolve => {
 51→  markUpdateReadyForDownload = () => {
 52→    isUpdateReadyForDownload = true;
 53→    resolve(true);
 54→  };
 55→});
 56→const updateSW = registerSW({
 57→  immediate: true,
 58→  onNeedRefresh: markUpdateReadyForDownload,
 59→});
