184→  saveFile: (contents, defaultFilename) => {
185→    const temp = document.createElement('a');
186→    temp.style = 'display: none';
187→    temp.download = defaultFilename;
188→    temp.rel = 'noopener';
189→
190→    const blob = new Blob([contents]);
191→    temp.href = URL.createObjectURL(blob);
192→    temp.dispatchEvent(new MouseEvent('click'));
193→  },
